content.text:
{
  "name": "A-Star轮速编码器",
  "name_en": "A-Star Wheel Speed Encoder",
  "manufacturer": "Pololu",
  "description": "这是一种安装在移动小车车轮上的旋转编码器测速装置，通常与A-Star控制板配合使用，用于根据车轮转动脉冲计算轮速和车辆行驶速度，常见于机器人小车与自动驾驶实验平台。",
  "description_en": "This is a wheel-mounted rotary encoder speed sensing device, typically used with an A-Star controller board, for calculating wheel speed and vehicle motion from encoder ticks. It is commonly used in robotic cars and autonomous vehicle lab platforms.",
  "actions": [
    {
      "action_name": "auto-update",
      "description": "更新轮速编码器读数并计算当前速度。",
      "description_en": "Update the wheel encoder reading and compute the current speed."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "以线程化方式返回当前轮速测量值。",
      "description_en": "Return the current wheel speed measurement in threaded operation."
    },
    {
      "action_name": "auto-shutdown",
      "description": "停止轮速编码器的后台采集过程。",
      "description_en": "Stop the background acquisition process of the wheel speed encoder."
    }
  ],
  "tag_hints": [
    "wheel encoder",
    "speed measurement",
    "robot car",
    "odometry",
    "rotary encoder",
    "mobile robotics",
    "A-Star controller"
  ]
}

